powerpagecomponent.content:
{
  "description": "Allowlist of columns the browser may write on contact. Two trigger columns: al_claimrequest, which carries the id of the case being claimed (AD-076), and al_signoffrequest, which carries the T&C attestation as JSON (AD-099). Each is acted on by its own plug-in, which checks the contact's web role server-side. Everything a contact record actually holds - name, email, the web roles - stays off this list, so exposing contact to the Web API grants the page these two writes and nothing else.",
  "value": "al_claimrequest,al_signoffrequest,al_regraderequest",
  "source": 0
}
